class Solution:
    def climbStairs(self, n: int) -> int:
        if n <= 2:
            return n

        dp = [0] * (n + 1)
        dp[1] = 1
        dp[2] = 2

        for i in range(3, n + 1):
            dp[i] = dp[i - 1] + dp[i - 2]

        return dp[n]

class Solution:
    def climbStairs(self, n: int) -> int:
        memo = {}

        def dfs(x):
            if x <= 2:
                return x

            if x in memo:
                return memo[x]

            memo[x] = dfs(x - 1) + dfs(x - 2)
            return memo[x]

        return dfs(n)

class Solution:
    def coinChange(self, coins: List[int], amount: int) -> int:
        dp = [amount + 1] * (amount + 1)
        dp[0] = 0

        for i in range(1, amount + 1):
            for coin in coins:
                if coin <= i:
                    dp[i] = min(dp[i], dp[i - coin] + 1)

        return -1 if dp[amount] == amount + 1 else dp[amount]

class Solution:
    def coinChange(self, coins: List[int], amount: int) -> int:
        memo = {}

        def dfs(x):
            if x == 0:
                return 0

            if x < 0:
                return float("inf")

            if x in memo:
                return memo[x]

            best = float("inf")

            for coin in coins:
                best = min(best, dfs(x - coin) + 1)

            memo[x] = best
            return best

        ans = dfs(amount)

        return -1 if ans == float("inf") else ans

class Solution:
    def uniquePaths(self, m: int, n: int) -> int:
        dp = [[0] * n for _ in range(m)]

        for i in range(m):
            dp[i][0] = 1

        for j in range(n):
            dp[0][j] = 1

        for i in range(1, m):
            for j in range(1, n):
                dp[i][j] = dp[i - 1][j] + dp[i][j - 1]

        return dp[m - 1][n - 1]

class Solution:
    def permute(self, nums: List[int]) -> List[List[int]]:
        ans = []

        def backtrack(path, remaining):
            if not remaining:
                ans.append(path[:])
                return

            for i in range(len(remaining)):
                path.append(remaining[i])

                new_remaining = remaining[:i] + remaining[i + 1:]
                backtrack(path, new_remaining)

                path.pop()

        backtrack([], nums)
        return ans

class Solution:
    def subsets(self, nums: List[int]) -> List[List[int]]:
        ans = []

        def backtrack(i, path):
            ans.append(path[:])

            for j in range(i, len(nums)):
                path.append(nums[j])
                backtrack(j + 1, path)
                path.pop()

        backtrack(0, [])
        return ans

class Solution:
    def levelOrder(self, root: Optional[TreeNode]) -> List[List[int]]:
        if not root:
            return []

        queue = [root]
        ans = []

        while queue:
            level = []

            for _ in range(len(queue)):
                node = queue.pop(0)
                level.append(node.val)

                if node.left:
                    queue.append(node.left)

                if node.right:
                    queue.append(node.right)

            ans.append(level)

        return ans

class Solution:
    def numIslands(self, grid: List[List[str]]) -> int:
        rows = len(grid)
        cols = len(grid[0])

        parent = list(range(rows * cols))
        size = [1] * (rows * cols)
        count = 0

        for i in range(rows):
            for j in range(cols):
                if grid[i][j] == "1":
                    count += 1

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(a, b):
            nonlocal count

            ra = find(a)
            rb = find(b)

            if ra == rb:
                return

            if size[ra] < size[rb]:
                ra, rb = rb, ra

            parent[rb] = ra
            size[ra] += size[rb]
            count -= 1

        for i in range(rows):
            for j in range(cols):
                if grid[i][j] != "1":
                    continue

                idx = i * cols + j

                if i + 1 < rows and grid[i + 1][j] == "1":
                    union(idx, (i + 1) * cols + j)

                if j + 1 < cols and grid[i][j + 1] == "1":
                    union(idx, i * cols + j + 1)

        return count

class Solution:
    def minimumDeletions(self, nums: List[int]) -> int:
        n = len(nums)

        maxx_ind = nums.index(max(nums))
        minn_ind = nums.index(min(nums))

        left = max(maxx_ind, minn_ind) + 1
        right = n - min(maxx_ind, minn_ind)

        max_left_min_right = maxx_ind + 1 + (n - minn_ind)
        min_left_max_right = minn_ind + 1 + (n - maxx_ind)

        return min(left, right, max_left_min_right, min_left_max_right)

