class Solution:
    def divide(self, dividend: int, divisor: int) -> int:

        if dividend == -2147483648 and divisor == -1:
            return 2147483647

        negative = (dividend < 0) != (divisor < 0)

        dividend = abs(dividend)
        divisor = abs(divisor)

        quotient = 0

        while dividend >= divisor:

            value = divisor
            count = 1

            while value + value <= dividend:
                value += value
                count += count

            dividend -= value
            quotient += count

        if negative:
            return -quotient

        return quotient

class Solution:
    def firstStableIndex(self, nums: list[int], k: int) -> int:
        ind=None
        if len(nums)==1 and nums[0]<=k:
            return 0
        for i in range(len(nums)):
            if max(nums[0:i+1])-min(nums[i:len(nums)])<=k:
                if ind==None or i<ind:
                    ind=i
        if ind==None:
            return -1
        return ind

class Solution:
    def uniformArray(self, nums1: list[int]) -> bool:
        odd = None

        for x in nums1:
            if x % 2 != 0:
                odd = x
                break

        if odd is None:
            return True

        nums2 = []

        for x in nums1:
            if x % 2 == 0:
                nums2.append(x - odd)
            else:
                nums2.append(x)

        return True

class Solution:
    def uniformArray(self, nums1: list[int]) -> bool:
        odd = None

        for x in nums1:
            if x % 2 != 0:
                if odd is None or x < odd:
                    odd = x

        if odd is None:
            return True

        for x in nums1:
